class Compresor:
    def __init__(self, algoritmo):
        self.algoritmo = algoritmo
    def comprimir(self, datos):
        return self.algoritmo.aplicar(datos)

class Zip:
    def aplicar(self, d): return "zip:" + d
class Gzip:
    def aplicar(self, d): return "gz:" + d

c = Compresor(Zip())
c.algoritmo = Gzip()
print(c.comprimir("hola"))

class Canal:
    def __init__(self):
        self.subs = []
    def suscribir(self, f):
        self.subs.append(f)
    def desuscribir(self, f):
        self.subs.remove(f)
    def publicar(self, video):
        for f in self.subs:
            f(video)

def ana(v): print("Ana vio", v)
def luis(v): print("Luis vio", v)
def eva(v): print("Eva vio", v)

c = Canal()
for f in (ana, luis, eva):
    c.suscribir(f)
c.desuscribir(luis)
c.publicar("Clase 1")
c.suscribir(luis)
c.publicar("Clase 2")

